<?php
session_start();require_once '../shared/config.php';requireLogin('customer','login.php');
$db=getDB();$orderId=intval($_GET['order_id']??0);
$stmt=$db->prepare("SELECT o.*,i.name item_name,v.store_name FROM orders o JOIN items i ON o.item_id=i.id JOIN vendors v ON o.vendor_id=v.id WHERE o.id=? AND o.customer_id=?");
$stmt->execute([$orderId,$_SESSION['customer_id']]);$order=$stmt->fetch();
if(!$order){header('Location: home.php');exit;}
